static double ClampDeadband(double deadband) {
  if (std::isnan(deadband)) {
    return 0.0;
  }
  return std::clamp(deadband, 0.0, std::nextafter(1.0, 0.0));
}

DualSenseController::DualSenseController(int port)
    : DualSenseController{DriverStation::GetGenericHID(port)} {}

DualSenseController::DualSenseController(GenericHID& hid)
    : m_hid{&hid} {
  prosdk::util::ReportUsage("HID", hid.GetPort(), "DualSenseController");
}

